WITH base AS (SELECT *, amount + discount AS amount_plus_discount FROM orders WHERE store_id IS NOT NULL AND customer_id = 21), orders_stats AS (SELECT CASE WHEN shipping_fee >= 40 THEN 'high' WHEN shipping_fee >= 13 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, MIN(discount) AS min_discount FROM base GROUP BY CASE WHEN shipping_fee >= 40 THEN 'high' WHEN shipping_fee >= 13 THEN 'mid' ELSE 'low' END) SELECT shipping_fee_bucket, min_discount FROM orders_stats
